"use strict";(self.webpackChunkchatgpt_shortcut=self.webpackChunkchatgpt_shortcut||[]).push([["68276"],{82979(t){t.exports=JSON.parse('{"id":8144,"title":"\u9178\u83DC\u9C7C\u201D\u7684\u521B\u610F\u6D77\u62A5","description":"\\n\\n\u5E2E\u6211\u751F\u6210\u4E00\u5F20\u201C\u9178\u83DC\u9C7C\u201D\u7684\u521B\u610F\u6D77\u62A5,\u8981\u6C42:\\n\\n1\u3001\u6784\u5EFA5\u5C42\u60AC\u6D6E\u5206\u5C42\u7ED3\u6784(\u9ED1\u5E95\u80CC\u666F),\u4ECE\u9876\u5C42\u5230\u4E0B\u5C42\u4F9D\u6B21\u5C55\u793A:\u9876\u5C42: [\u7075\u9B42\u8C03\u5473/\u9999\u6599,\u4F8B:\u82B1\u6912\u3001\u7EA2\u8FA3\u6912] (\u5B9E\u7269\u7279\u5199+\u5149\u6CFD\u611F) ;\u4E2D\u5C42: [\u8F85\u52A9\u98DF\u6750,\u4F8B:\u8001\u8C46\u8150\u3001\u8C46\u76AE\u3001\u9178\u83DC] (\u81EA\u7136\u6563\u843D+\u52A8\u6001\u6A21\u7CCA,\u6A21\u62DF\u4E0B\u843D) ;\u6838\u5FC3: [\u4E3B\u98DF\u6750\u8F7D\u4F53\uFF0C\u4F8B\uFF1A\u6446\u653E\u6574\u9F50\u7684\u591A\u4E2A\u9C7C\u7247] (\u7ACB\u4F53\u5448\u73B0+\u9171\u6C41\u5305\u88F9) ;\u57FA\u5E95:[\u98CE\u5473\u6C64\u5E95/\u9171\u6C41,\u76DB\u4E8E\u900F\u660E\u5BB9\u5668] (\u6807\u6CE8[[\u6C64\u5E95\u540D] +[\u98CE\u5473\u5173\u952E\u8BCD,\u4F8B: creamy&earthy flavor]\u300D ,\u52A0\u84B8\u6C7D\u7EBF\u548C\u6CB9\u73E0\u98DE\u6E85) ;\u5E95\u5C42: [\u5B8C\u6574\u83DC\u54C1\u6446\u76D8,\u4F8B:\u76DB\u4E8E\u76D8\u5B50\u4E2D\u7684\u9178\u83DC\u9C7C] (\u6492\u8F85\u52A9\u98DF\u6750+\u661F\u5149\u70B9\u7F00,\u5468\u56F4\u914D\u9910\u5177/\u914D\u83DC\u88C5\u9970)\u3002\\n\\n2\u3001\u98CE\u683C:\u9ED1\u5E95\u5BF9\u6BD4+\u9AD8\u9971\u548C\u8272\u5F69,\u6BCF\u5C42\u7528\u5F27\u5F62\u7BAD\u5934+\u53CC\u8BED\u6807\u6CE8,\u5F3A\u5316\u300C\u4ECE\u539F\u6599\u5230\u6210\u54C1\u300D\u7684\u70F9\u996A\u903B\u8F91\uFF1B\\n\\n3\u3001\u6C1B\u56F4:\u52A0\u5165\u70ED\u6C14\u3001\u9999\u6599\u788E\u5C51\u98DE\u6E85\u3001\u6CB9\u5149\u53CD\u5C04\u7B49\u52A8\u6001\u7EC6\u8282,\u8BA9\u753B\u9762\u6709\u201C\u521A\u51FA\u9505\u201D\u7684\u9C9C\u6D3B\u611F\u3002\\n\\n4\u3001\u538B\u7F29\u6574\u4F53\u89C6\u89C9\u5360\u6BD4(\u901A\u8FC7\u8C03\u6574\u6784\u56FE\u6BD4\u4F8B) ,\u8BA9\u6240\u6709\u5206\u5C42\u5143\u7D20\u7D27\u51D1\u5C45\u4E2D,\u56DB\u5468\u4FDD\u7559\u5145\u8DB3\u9ED1\u8272\u8D1F\u7A7A\u95F4(\u907F\u514D\u5143\u7D20\u62E5\u6324/\u6EA2\u51FA,\u540C\u65F6\u589E\u5F3A\u89C6\u89C9\u805A\u7126\u6027)","owner":"kingssong","upvotes":7,"downvotes":0,"upvoteDifference":7,"updatedAt":"2026-04-13T20:38:48.882Z"}')}}]);